storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd45: rowUpdateCachedGeneric for [R2, R3) (mls 4, rowLog 5), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd45(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0x9E3779B100000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $31, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $5, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  64(R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $5, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $31, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch45: rowFindBestMatch (noDict, mls 4, rowLog 5) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch45(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd45(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0x9E3779B100000000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $5, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd45(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0x9E3779B100000000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $5, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0x9E3779B100000000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $5, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $31, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD2  (R6), [V1.H8, V2.H8]
	VCMEQ V0.B16, V1.B16, V1.B16
	VCMEQ V0.B16, V2.B16, V2.B16
	WORD  $0x0f0a8421 // VSHRN $6, V1.H8, V1.B8 (Go 1.25's assembler lacks VSHRN)
	WORD  $0x0f0a8442 // VSHRN $6, V2.H8, V2.B8 (Go 1.25's assembler lacks VSHRN)
	VSLI  $4, V2.B8, V1.B8
	VMOV  V1.D[0], R11
	LSLW  $1, R10, R12
	ROR   R12, R11, R11
	AND   $0x5555555555555555, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16>>1, R10, R16
	ANDW  $31, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $31, R16, R16
	MOVW  $31, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow45(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 4,
// rowLog 5: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow45(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch45(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch45(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch45(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0x9E3779B100000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $5, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  64(R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd46: rowUpdateCachedGeneric for [R2, R3) (mls 4, rowLog 6), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd46(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0x9E3779B100000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $63, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $6, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  64(R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  32(R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $6, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $63, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch46: rowFindBestMatch (noDict, mls 4, rowLog 6) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch46(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd46(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0x9E3779B100000000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $6, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  32(R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd46(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0x9E3779B100000000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $6, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  32(R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0x9E3779B100000000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $6, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $63, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD4  (R6), [V1.B16, V2.B16, V3.B16, V4.B16]
	VCMEQ V0.B16, V1.B16, V1.B16
	VCMEQ V0.B16, V2.B16, V2.B16
	VCMEQ V0.B16, V3.B16, V3.B16
	VCMEQ V0.B16, V4.B16, V4.B16
	VSRI  $1, V1.B16, V2.B16
	VSRI  $1, V3.B16, V4.B16
	VSRI  $2, V2.B16, V4.B16
	VSRI  $4, V4.B16, V4.B16
	WORD  $0x0f0c8484 // VSHRN $4, V4.H8, V4.B8 (Go 1.25's assembler lacks VSHRN)
	VMOV  V4.D[0], R11
	ROR   R10, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16, R10, R16
	ANDW  $63, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $63, R16, R16
	MOVW  $63, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow46(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 4,
// rowLog 6: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow46(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch46(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch46(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch46(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0x9E3779B100000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $6, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  64(R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  32(R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd54: rowUpdateCachedGeneric for [R2, R3) (mls 5, rowLog 4), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd54(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0xCF1BBCDCBB000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $15, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $4, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $4, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $15, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch54: rowFindBestMatch (noDict, mls 5, rowLog 4) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch54(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd54(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0xCF1BBCDCBB000000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $4, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd54(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0xCF1BBCDCBB000000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $4, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0xCF1BBCDCBB000000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $4, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $15, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD1  (R6), [V1.B16]
	VCMEQ V0.B16, V1.B16, V1.B16
	WORD  $0x0f0c8421 // VSHRN $4, V1.H8, V1.B8 (Go 1.25's assembler lacks VSHRN)
	VMOV  V1.D[0], R11
	LSLW  $2, R10, R12
	ROR   R12, R11, R11
	AND   $0x8888888888888888, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16>>2, R10, R16
	ANDW  $15, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $15, R16, R16
	MOVW  $15, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow54(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 5,
// rowLog 4: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow54(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch54(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch54(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch54(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0xCF1BBCDCBB000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $4, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd55: rowUpdateCachedGeneric for [R2, R3) (mls 5, rowLog 5), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd55(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0xCF1BBCDCBB000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $31, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $5, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  64(R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $5, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $31, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch55: rowFindBestMatch (noDict, mls 5, rowLog 5) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch55(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd55(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0xCF1BBCDCBB000000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $5, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd55(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0xCF1BBCDCBB000000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $5, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0xCF1BBCDCBB000000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $5, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $31, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD2  (R6), [V1.H8, V2.H8]
	VCMEQ V0.B16, V1.B16, V1.B16
	VCMEQ V0.B16, V2.B16, V2.B16
	WORD  $0x0f0a8421 // VSHRN $6, V1.H8, V1.B8 (Go 1.25's assembler lacks VSHRN)
	WORD  $0x0f0a8442 // VSHRN $6, V2.H8, V2.B8 (Go 1.25's assembler lacks VSHRN)
	VSLI  $4, V2.B8, V1.B8
	VMOV  V1.D[0], R11
	LSLW  $1, R10, R12
	ROR   R12, R11, R11
	AND   $0x5555555555555555, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16>>1, R10, R16
	ANDW  $31, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $31, R16, R16
	MOVW  $31, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow55(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 5,
// rowLog 5: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow55(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch55(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch55(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch55(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0xCF1BBCDCBB000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $5, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  64(R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd56: rowUpdateCachedGeneric for [R2, R3) (mls 5, rowLog 6), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd56(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0xCF1BBCDCBB000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $63, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $6, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  64(R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  32(R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $6, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $63, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch56: rowFindBestMatch (noDict, mls 5, rowLog 6) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch56(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd56(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0xCF1BBCDCBB000000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $6, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  32(R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd56(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0xCF1BBCDCBB000000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $6, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  32(R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0xCF1BBCDCBB000000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $6, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $63, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD4  (R6), [V1.B16, V2.B16, V3.B16, V4.B16]
	VCMEQ V0.B16, V1.B16, V1.B16
	VCMEQ V0.B16, V2.B16, V2.B16
	VCMEQ V0.B16, V3.B16, V3.B16
	VCMEQ V0.B16, V4.B16, V4.B16
	VSRI  $1, V1.B16, V2.B16
	VSRI  $1, V3.B16, V4.B16
	VSRI  $2, V2.B16, V4.B16
	VSRI  $4, V4.B16, V4.B16
	WORD  $0x0f0c8484 // VSHRN $4, V4.H8, V4.B8 (Go 1.25's assembler lacks VSHRN)
	VMOV  V4.D[0], R11
	ROR   R10, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16, R10, R16
	ANDW  $63, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $63, R16, R16
	MOVW  $63, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow56(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 5,
// rowLog 6: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow56(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch56(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch56(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch56(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0xCF1BBCDCBB000000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $6, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  64(R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  32(R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd64: rowUpdateCachedGeneric for [R2, R3) (mls 6, rowLog 4), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd64(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0xCF1BBCDCBF9B0000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $15, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $4, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $4, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $15, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch64: rowFindBestMatch (noDict, mls 6, rowLog 4) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch64(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd64(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $4, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd64(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $4, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $4, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $15, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD1  (R6), [V1.B16]
	VCMEQ V0.B16, V1.B16, V1.B16
	WORD  $0x0f0c8421 // VSHRN $4, V1.H8, V1.B8 (Go 1.25's assembler lacks VSHRN)
	VMOV  V1.D[0], R11
	LSLW  $2, R10, R12
	ROR   R12, R11, R11
	AND   $0x8888888888888888, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16>>2, R10, R16
	ANDW  $15, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $15, R16, R16
	MOVW  $15, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow64(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 6,
// rowLog 4: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow64(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch64(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch64(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch64(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0xCF1BBCDCBF9B0000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $4, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd65: rowUpdateCachedGeneric for [R2, R3) (mls 6, rowLog 5), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd65(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0xCF1BBCDCBF9B0000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $31, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $5, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  64(R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $5, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $31, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch65: rowFindBestMatch (noDict, mls 6, rowLog 5) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch65(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd65(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $5, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd65(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $5, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $5, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $31, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD2  (R6), [V1.H8, V2.H8]
	VCMEQ V0.B16, V1.B16, V1.B16
	VCMEQ V0.B16, V2.B16, V2.B16
	WORD  $0x0f0a8421 // VSHRN $6, V1.H8, V1.B8 (Go 1.25's assembler lacks VSHRN)
	WORD  $0x0f0a8442 // VSHRN $6, V2.H8, V2.B8 (Go 1.25's assembler lacks VSHRN)
	VSLI  $4, V2.B8, V1.B8
	VMOV  V1.D[0], R11
	LSLW  $1, R10, R12
	ROR   R12, R11, R11
	AND   $0x5555555555555555, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16>>1, R10, R16
	ANDW  $31, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $31, R16, R16
	MOVW  $31, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow65(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 6,
// rowLog 5: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow65(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch65(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch65(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch65(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0xCF1BBCDCBF9B0000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $5, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  64(R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// rowUpd66: rowUpdateCachedGeneric for [R2, R3) (mls 6, rowLog 6), prefetching
// each new hash's row. R21 = p. Clobbers R0-R17, R19, R20.
TEXT ·rowUpd66(SB), NOSPLIT|NOFRAME, $0-0
	CMPW  R3, R2
	BHS   done
	MOVD  P_HASHTABLE, R4
	MOVD  P_TAGTABLE, R5
	MOVD  P_CACHE, R6
	MOVD  P_B, R7
	MOVWU P_BASEIDX, R8
	SUB   R8, R7, R7            // b - baseIdx (no calls: never seen by the GC)
	MOVD  $0xCF1BBCDCBF9B0000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVW  $63, R17

loop:
	ADD   R2, R7, R12
	MOVD  8(R12), R13
	MUL   R9, R13, R13
	EOR   R10, R13, R13
	LSR   R11, R13, R13         // newHash
	LSRW  $8, R13, R14
	LSLW  $6, R14, R14
	ADD   R14<<2, R4, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  64(R15), PLDL1KEEP
	ADD   R14, R5, R15
	PRFM  (R15), PLDL1KEEP
	PRFM  32(R15), PLDL1KEEP
	ANDW  $7, R2, R12
	MOVWU (R6)(R12<<2), R16     // hash
	MOVW  R13, (R6)(R12<<2)
	LSRW  $8, R16, R14
	LSLW  $6, R14, R14       // relRow
	MOVBU (R5)(R14), R12
	SUBW  $1, R12
	ANDSW $63, R12, R12
	CSELW EQ, R17, R12, R12     // head 0 wraps to rowMask (C: cmove)
	MOVB  R12, (R5)(R14)
	ADD   R12, R14, R14
	MOVB  R16, (R5)(R14)
	MOVW  R2, (R4)(R14<<2)
	ADDW  $1, R2
	CMPW  R3, R2
	BLO   loop

done:
	RET

// rowSearch66: rowFindBestMatch (noDict, mls 6, rowLog 6) at R0 = ip, R21 = p.
// Returns R0 = ml (below 4: none; -1: a table entry at or after ip, impossible),
// R1 = offBase. Clobbers R0-R17, R19, R20, V0-V4.
TEXT ·rowSearch66(SB), NOSPLIT, $288-0
	MOVD  R0, S_IP
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	ADDW  R0, R5, R6
	MOVW  R6, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R7
	MOVWU P_MAXDIST, R8
	SUBW  R7, R6, R9
	CMPW  R8, R9
	BLS   lowok
	SUBW  R8, R6, R7

lowok:
	MOVWU P_ISDICT, R9
	CBZW  R9, lowset
	MOVWU P_LOWEST, R7

lowset:
	MOVW  R7, S_LOWLIM
	MOVWU P_SKIP, R9
	CBNZW R9, skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVD  P_NEXT, R9
	MOVWU (R9), R2
	MOVWU S_CURR, R3
	SUBW  R2, R3, R9
	CMPW  $384, R9
	BLS   upd
	ADDW  $96, R2, R3
	CALL  ·rowUpd66(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVD  P_B, R4
	MOVD  P_CACHE, R5
	MOVWU P_BASEIDX, R15
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R13
	MOVD  P_TAGTABLE, R14
	MOVWU S_CURR, R2
	SUBW  $32, R2
	MOVD  $8, R6

fill:
	SUBW  R15, R2, R7
	MOVD  (R4)(R7), R8
	MUL   R12, R8, R8
	EOR   R10, R8, R8
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $6, R9, R9
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  32(R16), PLDL1KEEP
	ANDW  $7, R2, R7
	MOVW  R8, (R5)(R7<<2)
	ADDW  $1, R2
	SUBS  $1, R6
	BNE   fill
	MOVWU S_CURR, R3
	SUBW  $32, R3, R2

upd:
	CALL  ·rowUpd66(SB)
	MOVD  P_NEXT, R9
	MOVWU S_CURR, R6
	MOVW  R6, (R9)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVD  P_B, R4
	MOVD  S_IP, R0
	ADD   R0, R4, R7
	MOVD  8(R7), R8
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MUL   R12, R8, R8
	MOVD  P_SALT, R10
	EOR   R10, R8, R8
	MOVD  P_HSHIFT, R11
	LSR   R11, R8, R8
	LSRW  $8, R8, R9
	LSLW  $6, R9, R9
	MOVD  P_HASHTABLE, R13
	ADD   R9<<2, R13, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  64(R16), PLDL1KEEP
	MOVD  P_TAGTABLE, R14
	ADD   R9, R14, R16
	PRFM  (R16), PLDL1KEEP
	PRFM  32(R16), PLDL1KEEP
	MOVD  P_CACHE, R5
	ANDW  $7, R6, R7
	MOVWU (R5)(R7<<2), R1
	MOVW  R8, (R5)(R7<<2)
	B     havehash

skipping:
	MOVD  (R4)(R0), R1
	MOVD  $0xCF1BBCDCBF9B0000, R12
	MUL   R12, R1, R1
	MOVD  P_SALT, R10
	EOR   R10, R1, R1
	MOVD  P_HSHIFT, R11
	LSR   R11, R1, R1
	MOVD  P_NEXT, R9
	MOVW  R6, (R9)

havehash:
	// R1 = hash, R4 = b, R0 = ip
	MOVD  P_ENTROPY, R9
	MOVWU (R9), R10
	ADDW  R1, R10, R10
	MOVW  R10, (R9)             // collect salt entropy
	ANDW  $0xFF, R1, R2
	MOVW  R2, S_TAG
	LSRW  $8, R1, R3
	LSLW  $6, R3, R3         // relRow
	MOVD  P_HASHTABLE, R5
	ADD   R3<<2, R5, R5         // row
	MOVD  P_TAGTABLE, R6
	ADD   R3, R6, R6            // tagRow
	MOVD  P_ILIMIT, R8
	MOVWU P_BASEIDX, R9
	SUB   R9, R4, R7            // b - baseIdx: an index addresses b directly
	MOVWU S_CURR, R20
	MOVWU P_ATTEMPTS, R14
	MOVBU (R6), R10
	ANDW  $63, R10         // head

	// matches: tags equal to tag, rotated right by head (C: ZSTD_row_getNEONMask)
	VDUP  R2, V0.B16
	VLD4  (R6), [V1.B16, V2.B16, V3.B16, V4.B16]
	VCMEQ V0.B16, V1.B16, V1.B16
	VCMEQ V0.B16, V2.B16, V2.B16
	VCMEQ V0.B16, V3.B16, V3.B16
	VCMEQ V0.B16, V4.B16, V4.B16
	VSRI  $1, V1.B16, V2.B16
	VSRI  $1, V3.B16, V4.B16
	VSRI  $2, V2.B16, V4.B16
	VSRI  $4, V4.B16, V4.B16
	WORD  $0x0f0c8484 // VSHRN $4, V4.H8, V4.B8 (Go 1.25's assembler lacks VSHRN)
	VMOV  V4.D[0], R11
	ROR   R10, R11, R11
	MOVWU S_LOWLIM, R12
	MOVD  ZR, R13
	ADD   $8, RSP, R15          // candidate buffer

gather:
	CBZ   R11, insert
	CBZW  R14, insert
	RBIT  R11, R16
	CLZ   R16, R16
	SUB   $1, R11, R17
	AND   R17, R11, R11
	ADDW  R16, R10, R16
	ANDW  $63, R16
	CBZW  R16, gather           // the head entry is not a candidate
	MOVWU (R5)(R16<<2), R17
	CMPW  R12, R17
	BLO   insert                // below lowLimit: stop
	// lowLimit <= R17 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R7 + R17 lies in b[0:ip]; the compare loop reads only
	// buffered candidates, which all passed this check.
	CMPW  R20, R17
	BHS   bad
	ADD   R17, R7, R19
	PRFM  (R19), PLDL1KEEP
	MOVW  R17, (R15)(R13<<2)
	ADD   $1, R13
	SUBW  $1, R14
	B     gather

insert:
	MOVBU (R6), R16
	SUBW  $1, R16
	ANDSW $63, R16, R16
	MOVW  $63, R17
	CSELW EQ, R17, R16, R16
	MOVB  R16, (R6)
	MOVWU S_TAG, R17
	MOVB  R17, (R6)(R16)
	MOVD  P_NEXT, R19
	MOVWU (R19), R17
	MOVW  R17, (R5)(R16<<2)
	ADDW  $1, R17
	MOVW  R17, (R19)            // nextToUpdate++

	MOVD $3, R10
	MOVD ZR, R11
	MOVD ZR, R12
	ADD  R0, R4, R1
	SUB  R0, R8, R8             // iLimit - ip

cmp:
	CMP   R13, R12
	BHS   done
	MOVWU (R15)(R12<<2), R3
	ADD   $1, R12
	ADD   R3, R7, R2
	ADD   R10, R2, R16
	MOVWU -3(R16), R16
	ADD   R10, R1, R17
	MOVWU -3(R17), R17
	CMPW  R16, R17
	BNE   cmp
	MOVD  ZR, R14

cnt8:
	ADD  $8, R14, R16
	CMP  R8, R16
	BHI  cnttail
	MOVD (R2)(R14), R16
	MOVD (R1)(R14), R17
	EOR  R16, R17, R17
	CBNZ R17, cntdiff
	ADD  $8, R14
	B    cnt8

cntdiff:
	RBIT R17, R17
	CLZ  R17, R17
	ADD  R17>>3, R14, R14
	B    cntdone

cnttail:
	CMP   R8, R14
	BHS   cntdone
	MOVBU (R2)(R14), R16
	MOVBU (R1)(R14), R17
	CMPW  R16, R17
	BNE   cntdone
	ADD   $1, R14
	B     cnttail

cntdone:
	CMP  R10, R14
	BLE  cmp
	MOVD R14, R10
	MOVD R3, R11
	CMP  R8, R14
	BNE  cmp

done:
	MOVD R10, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R10
	BLE  ret
	MOVWU S_CURR, R1
	SUBW R11, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyRow66(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 6,
// rowLog 6: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyRow66(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·rowSearch66(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·rowSearch66(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·rowSearch66(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVW  ZR, P_SKIP
	MOVD  P_NEXT, R0
	MOVWU (R0), R8              // idx
	MOVWU P_BASEIDX, R1
	SUBW  R1, R8, R0            // its position
	MOVD  ilimit+48(FP), R2
	SUB   R0, R2, R2
	TBNZ  $63, R2, reploop      // idx beyond ilimit: nothing to fill
	ADD   $1, R2
	CMP   $8, R2
	BLE   fillcnt
	MOVD  $8, R2

fillcnt:
	MOVD  P_CACHE, R3
	MOVD  $0xCF1BBCDCBF9B0000, R9
	MOVD  P_SALT, R10
	MOVD  P_HSHIFT, R11
	MOVD  P_HASHTABLE, R12
	MOVD  P_TAGTABLE, R13

fillloop:
	SUBW  R1, R8, R0
	MOVD  (R22)(R0), R4
	MUL   R9, R4, R4
	EOR   R10, R4, R4
	LSR   R11, R4, R4
	LSRW  $8, R4, R5
	LSLW  $6, R5, R5
	ADD   R5<<2, R12, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  64(R6), PLDL1KEEP
	ADD   R5, R13, R6
	PRFM  (R6), PLDL1KEEP
	PRFM  32(R6), PLDL1KEEP
	ANDW  $7, R8, R0
	MOVW  R4, (R3)(R0<<2)
	ADDW  $1, R8
	SUBS  $1, R2
	BNE   fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET
